 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    mark = max((v for v in set(x for row in grid for x in row) if v != bg), key=lambda c: sum(row.count(c) for row in grid))
    rows = [r for r in range(h) if mark in grid[r]]
    cols = [c for c in range(w) if any(grid[r][c] == mark for r in range(h))]
    top, bottom, left, right = min(rows), max(rows), min(cols), max(cols)
    # Fill every missing part of the frame boundary.
    for c in range(left, right + 1):
        if grid[top][c] == bg: out[top][c] = 2
        if grid[bottom][c] == bg: out[bottom][c] = 2
    for r in range(top, bottom + 1):
        if grid[r][left] == bg: out[r][left] = 2
        if grid[r][right] == bg: out[r][right] = 2
    # Repeated aligned marks identify a broken straight stroke, completed
    # throughout its interior span; preserve the original mark cells.
    for c in range(left + 1, right):
        if sum(grid[r][c] == mark for r in range(top + 1, bottom)) >= 2:
            for r in range(top + 1, bottom):
                if grid[r][c] == bg: out[r][c] = 2
    for r in range(top + 1, bottom):
        if sum(grid[r][c] == mark for c in range(left + 1, right)) >= 2:
            for c in range(left + 1, right):
                if grid[r][c] == bg: out[r][c] = 2
    return out

